def is_valid_word(word: str) -> bool:
    # Check minimum length of 3 characters
    if len(word) < 3:
        return False

    # Define vowels (both lowercase and uppercase)
    vowels = set('aeiouAEIOU')

    # Check if word contains only digits and English letters
    for char in word:
        if not (char.isdigit() or char.isalpha()):
            return False

    # Check for at least one vowel and one consonant
    has_vowel = False
    has_consonant = False

    for char in word:
        if char.isdigit():
            continue  # Skip digits
        if char in vowels:
            has_vowel = True
        else:  # It's a consonant (English letter that's not a vowel)
            has_consonant = True

    return has_vowel and has_consonant
```

