def maximumTime(s: str) -> str:
    # Convert string to list for easier manipulation
    time_list = list(s)

    # Handle hour digits
    # First hour digit (index 0)
    if time_list[0] == '?':
        # If second hour digit is known and > '1', then first must be '0'
        if time_list[1] != '?' and time_list[1] > '1':
            time_list[0] = '0'
        # Otherwise, try to make it '1' if possible (since 10-11 are valid)
        elif time_list[1] == '?' or time_list[1] <= '1':
            time_list[0] = '1'
        else:
            time_list[0] = '0'
    # If first digit is '0' or '1', we're fine

    # Second hour digit (index 1)
    if time_list[1] == '?':
        if time_list[0] == '0':
            # If first digit is '0', second can be 0-9 (00-09)
            time_list[1] = '9'
        elif time_list[0] == '1':
            # If first digit is '1', second can be 0-1 (10-11)
            time_list[1] = '1'
        else:
            # First digit must be 0 (if somehow not set yet)
            time_list[1] = '9'

    # Handle minute digits
    # First minute digit (index 3)
    if time_list[3] == '?':
        time_list[3] = '5'  # Max first digit in minutes is 5

    # Second minute digit (index 4)
    if time_list[4] == '?':
        time_list[4] = '9'  # Max second digit in minutes is 9

    return ''.join(time_list)
```

