def number_of_special_letters(word: str) -> int:
    # Convert the word to sets of lowercase and uppercase letters
    lower_set = set()
    upper_set = set()

    for char in word:
        if char.islower():
            lower_set.add(char)
        else:
            upper_set.add(char.lower())  # Convert uppercase to lowercase for comparison

    # Count letters that appear in both sets
    special_count = 0
    for letter in lower_set:
        if letter in upper_set:
            special_count += 1

    return special_count
