def number_of_right_triangles(grid):
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])

    # Count ones in each row and column
    row_count = [0] * m
    col_count = [0] * n

    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                row_count[i] += 1
                col_count[j] += 1

    result = 0

    # For each cell with 1, count how many right triangles have this cell as the right-angle vertex
    # If a cell (i,j) is the right-angle vertex, we need:
    # - one more 1 in the same row i (row_count[i] - 1 choices)
    # - one more 1 in the same column j (col_count[j] - 1 choices)
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                # Number of ways to choose one more point in row i and one more point in column j
                result += (row_count[i] - 1) * (col_count[j] - 1)

    return result
```

