def countBeautiful(low, high, k):
    def is_beautiful(num):
        s = str(num)
        even_count = sum(1 for d in s if int(d) % 2 == 0)
        odd_count = len(s) - even_count
        return even_count == odd_count and num % k == 0

    # Count beautiful numbers from 1 to n
    def count_up_to(n):
        count = 0
        for num in range(1, n + 1):
            if is_beautiful(num):
                count += 1
        return count

    return count_up_to(high) - count_up_to(low - 1)
```

