def min_length(s: str) -> int:
    stack = []

    for char in s:
        # Check if we can form "AB" or "CD" with the top of the stack and current character
        if stack and ((stack[-1] == 'A' and char == 'B') or (stack[-1] == 'C' and char == 'D')):
            stack.pop()  # Remove the matching pair
        else:
            stack.append(char)

    return len(stack)
