def beautiful_substrings(s: str, k: int) -> int:
    vowels_set = {'a', 'e', 'i', 'o', 'u'}
    count = 0

    # Try all possible substrings
    n = len(s)
    for i in range(n):
        vowels = 0
        consonants = 0
        for j in range(i, n):
            if s[j] in vowels_set:
                vowels += 1
            else:
                consonants += 1

            # Check if current substring is beautiful
            if vowels == consonants and (vowels * consonants) % k == 0:
                count += 1

    return count
```

