def incremovableSubarrays(nums):
    n = len(nums)
    count = 0

    # Try all possible subarrays [i, j]
    for i in range(n):
        for j in range(i, n):
            # Create the array after removing subarray [i, j]
            remaining = []
            for k in range(n):
                if k < i or k > j:
                    remaining.append(nums[k])

            # Check if remaining array is strictly increasing
            is_increasing = True
            for k in range(1, len(remaining)):
                if remaining[k] <= remaining[k-1]:
                    is_increasing = False
                    break

            if is_increasing:
                count += 1

    return count
```

