def permutation_difference(s: str, t: str) -> int:
    # Create a dictionary to store the index of each character in t
    t_indices = {char: idx for idx, char in enumerate(t)}

    # Calculate the sum of absolute differences
    total = 0
    for i, char in enumerate(s):
        total += abs(i - t_indices[char])

    return total
