def max_strength(nums):
    n = len(nums)
    max_strength = float('-inf')

    # Iterate through all non-empty subsets using bitmask
    for mask in range(1, 1 << n):
        product = 1
        for i in range(n):
            if mask & (1 << i):
                product *= nums[i]
        max_strength = max(max_strength, product)

    return max_strength
