def relocate_marbles(nums, moveFrom, moveTo):
    # Use a set to track occupied positions (since we only care about presence, not count)
    positions = set(nums)

    # Process each move
    for f, t in zip(moveFrom, moveTo):
        if f in positions:
            # Remove the from position and add the to position
            positions.remove(f)
            positions.add(t)

    # Return sorted list of occupied positions
    return sorted(positions)
```

