def longest_common_prefix(arr1, arr2):
    # Convert all numbers in arr1 to their string prefixes and store in a set
    prefixes = set()
    for num in arr1:
        s = str(num)
        for i in range(1, len(s) + 1):
            prefixes.add(s[:i])

    # Find the longest common prefix with numbers in arr2
    max_length = 0
    for num in arr2:
        s = str(num)
        # Check all prefixes of current number
        for i in range(len(s), 0, -1):
            prefix = s[:i]
            if prefix in prefixes:
                max_length = max(max_length, i)
                break  # No need to check shorter prefixes for this number

    return max_length
```

