def punishment_number(n):
    def can_partition(s, target):
        # Recursive helper to check if string s can be partitioned to sum to target
        if not s:
            return target == 0
        # Try all possible splits
        for i in range(1, len(s) + 1):
            num = int(s[:i])
            # Early pruning: if current number exceeds target, no need to continue
            if num > target:
                break
            if can_partition(s[i:], target - num):
                return True
        return False

    total = 0
    for i in range(1, n + 1):
        square = i * i
        square_str = str(square)
        if can_partition(square_str, i):
            total += square
    return total
```

