def minimumCost(source: str, target: str, original: list, changed: list, cost: list) -> int:
    # If lengths are different, impossible
    if len(source) != len(target):
        return -1

    # Create a graph for character transformations
    # There are 26 lowercase letters, so use 26x26 matrix
    INF = float('inf')
    # Initialize distance matrix
    dist = [[INF] * 26 for _ in range(26)]

    # Distance from a character to itself is 0
    for i in range(26):
        dist[i][i] = 0

    # Fill in the direct transformation costs
    for i in range(len(original)):
        u = ord(original[i]) - ord('a')
        v = ord(changed[i]) - ord('a')
        c = cost[i]
        # For multiple edges between same pair, take minimum
        if c < dist[u][v]:
            dist[u][v] = c

    # Floyd-Warshall algorithm to find shortest path between all pairs
    for k in range(26):
        for i in range(26):
            # Skip if no path to intermediate node k
            if dist[i][k] == INF:
                continue
            for j in range(26):
