                    dist[i][j] = dist[i][k] + dist[k][j]

    # Calculate total cost to convert source to target
    total_cost = 0
    for i in range(len(source)):
        if source[i] == target[i]:
            continue
        u = ord(source[i]) - ord('a')
        v = ord(target[i]) - ord('a')
        if dist[u][v] == INF:
            return -1
        total_cost += dist[u][v]

    return total_cost
