def countCompleteSubstrings(word: str, k: int) -> int:
    n = len(word)
    result = 0

    # For each possible number of distinct characters (1 to 26)
    for distinct_count in range(1, 27):
        window_size = distinct_count * k

        if window_size > n:
            break

        # Sliding window approach
        freq = [0] * 26
        left = 0

        for right in range(n):
            # Add current character to the window
            freq[ord(word[right]) - ord('a')] += 1

            # If window size exceeds window_size, shrink from left
            while right - left + 1 > window_size:
                freq[ord(word[left]) - ord('a')] -= 1
                left += 1

            # If window size equals window_size, check conditions
            if right - left + 1 == window_size:
                # Check if all characters appear exactly k times
                all_k_times = True
                for count in freq:
                    if count != 0 and count != k:
                        all_k_times = False
                        break

                if all_k_times:
                    # Check adjacent character difference condition
                    valid = True
                    for i in range(left + 1, right + 1):
                        if abs(ord(word[i]) - ord(word[i-1])) > 2:
                            valid = False
                            break

                    if valid:
                        result += 1

    return result
```

