def shortest_beautiful_substring(s: str, k: int) -> str:
    n = len(s)
    # Collect all substrings with exactly k ones
    beautiful_substrings = []

    for i in range(n):
        ones_count = 0
        for j in range(i, n):
            if s[j] == '1':
                ones_count += 1
            if ones_count == k:
                # Found a beautiful substring from i to j
                beautiful_substrings.append(s[i:j+1])
            elif ones_count > k:
                # No need to extend further as we already exceeded k ones
                break

    # If no beautiful substring exists
    if not beautiful_substrings:
        return ""

    # Find the minimum length among beautiful substrings
    min_len = min(len(sub) for sub in beautiful_substrings)

    # Filter substrings with minimum length
    candidates = [sub for sub in beautiful_substrings if len(sub) == min_len]

    # Return lexicographically smallest candidate
    return min(candidates)
