def can_split_array(nums, m):
    n = len(nums)

    # Base case: if array length is 1, it's already split
    if n == 1:
        return True

    # Precompute prefix sums for efficient subarray sum calculation
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + nums[i]

    def subarray_sum(i, j):
        # Sum of nums[i:j+1]
        return prefix[j + 1] - prefix[i]

    # Memoization dictionary
    memo = {}

    def can_split(i, j):
        # Check if subarray nums[i:j+1] can be split into (j-i+1) single elements
        if i == j:
            return True

        if (i, j) in memo:
            return memo[(i, j)]

        # Try all possible first splits: split into [i:k] and [k+1:j] for k in range(i, j)
        for k in range(i, j):
            left_len = k - i + 1
            right_len = j - k

            # Check if left subarray is valid (length 1 or sum >= m)
            left_valid = (left_len == 1) or (subarray_sum(i, k) >= m)
            # Check if right subarray is valid (length 1 or sum >= m)
            right_valid = (right_len == 1) or (subarray_sum(k + 1, j) >= m)

            # If both parts are valid, check if each can be further split
            if left_valid and right_valid:
                if can_split(i, k) and can_split(k + 1, j):
                    memo[(i, j)] = True
                    return True

        memo[(i, j)] = False
        return False

    return can_split(0, n - 1)
```

