def can_traverse_all_pairs(nums):
    n = len(nums)
    if n == 1:
        return True

    # Union-Find data structure
    parent = list(range(n))
    rank = [0] * n

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px == py:
            return
        if rank[px] < rank[py]:
            parent[px] = py
        elif rank[px] > rank[py]:
            parent[py] = px
        else:
            parent[py] = px
            rank[px] += 1

    # Map each prime factor to a list of indices having that factor
    prime_to_indices = {}

    # Factorize each number and record which indices have which prime factors
    for i, num in enumerate(nums):
        # Factorize num
        temp = num
        d = 2
        while d * d <= temp:
            if temp % d == 0:
                if d not in prime_to_indices:
                    prime_to_indices[d] = []
                prime_to_indices[d].append(i)
                while temp % d == 0:
                    temp //= d
            d += 1
        if temp > 1:
            if temp not in prime_to_indices:
                prime_to_indices[temp] = []
            prime_to_indices[temp].append(i)

    # For each prime factor, union all indices that share this factor
    for indices in prime_to_indices.values():
        for i in range(1, len(indices)):
            union(indices[0], indices[i])

    # Check if all indices are in the same connected component
    root = find(0)
    for i in range(1, n):
        if find(i) != root:
            return False

    return True
