def countSpecialPermutations(nums):
    MOD = 10**9 + 7
    n = len(nums)

    # Precompute which pairs are compatible (divisible in either direction)
    # compatible[i][j] = True if nums[i] and nums[j] are divisible in either direction
    compatible = [[False] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j:
                compatible[i][j] = (nums[i] % nums[j] == 0) or (nums[j] % nums[i] == 0)

    # dp[mask][last] = number of ways to arrange the elements represented by mask
    # such that the last element is at index 'last'
    # mask is a bitmask where bit i is 1 if element i is included in the permutation
    dp = [[0] * n for _ in range(1 << n)]

    # Base case: permutations of length 1
    for i in range(n):
        dp[1 << i][i] = 1

    # Iterate through all masks
    for mask in range(1, 1 << n):
        for last in range(n):
            # If last is not in mask, skip
            if not (mask & (1 << last)):
                continue

            # Try to extend the permutation by adding a new element 'curr'
            for curr in range(n):
                # If curr is already in mask, skip
                if mask & (1 << curr):
                    continue

                # If last and curr are compatible, extend the permutation
                if compatible[last][curr]:
                    new_mask = mask | (1 << curr)
                    dp[new_mask][curr] = (dp[new_mask][curr] + dp[mask][last]) % MOD

    # Sum all permutations that use all elements
    full_mask = (1 << n) - 1
    result = 0
    for i in range(n):
        result = (result + dp[full_mask][i]) % MOD

    return result
```

