def countGoodPartitions(nums):
    MOD = 10**9 + 7

    # Record the last occurrence index of each number
    last_occurrence = {}
    for i, num in enumerate(nums):
        last_occurrence[num] = i

    # Count the number of forced segments
    # A segment must end at or after the last occurrence of any number in it
    segments = 0
    end = 0

    for i, num in enumerate(nums):
        # Extend the current segment's end if necessary
        end = max(end, last_occurrence[num])

        # If we've reached the end of the current segment
        if i == end:
            segments += 1

    # The number of good partitions is 2^(segments - 1)
    # Because between each pair of consecutive segments, we can choose to partition or not
    # This gives us (segments - 1) choices, each with 2 options
    return pow(2, segments - 1, MOD)
```

